"C:\\WINDOWS\\System32\\WindowsPowerShell\\v1.0\\powershell.exe" -Command "
# Look for any freeze report that tracks FL18 package hashes  
# The 00_README_FIRST says the package self-hash must be recorded in \"external freeze report\"
# Search for any file that mentions the package self-hash or FL18 freeze
Get-ChildItem \"E:\\VPS\\reports\" -Recurse -Filter \"*.json\" -ErrorAction SilentlyContinue | 
  Where-Object { "'$_.Length -lt 50000 } |
  ForEach-Object {
    $content = Get-Content $_.FullName -Raw -ErrorAction SilentlyContinue
    if ($content -match "fl18|FL18|b0a2bd9|package_self" -and $content -match "hash") {
      Write-Output "$($_.FullName)"
    }
  } | Select-Object -First 15'

